{"command":"mkdir -p src && cat > src/cli.js <<'EOF'
const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

class Fail extends Error {}

function parse(s) {
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#([\s\S]*))?$/.exec(s)
  return { scheme: m[1], authority: m[2], path: m[3], query: m[4], fragment: m[5] }
}

function splitAuthority(a) {
  let userinfo
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); a = a.slice(at + 1) }
  const rb = a.lastIndexOf(']')
  const colon = a.indexOf(':', rb + 1)
  let host = a, port
  if (colon >= 0) { host = a.slice(0, colon); port = a.slice(colon + 1) }
  return { userinfo, host, port }
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const UNRESERVED = /^[A-Za-z0-9\-._~]$/

function pct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
  })
}

function check(s, name) {
  if (/%(?![0-9A-Fa-f]{2})/.test(s)) throw new Fail(`the ${name} has a truncated percent-encoding`)
}

function removeDots(path) {
  let inp = path
  const out = []
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out.pop()
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out.push(seg)
      inp = inp.slice(seg.length)
    }
  }
  return out.join('')
}

function normalize(c) {
  const scheme = c.scheme === undefined ? undefined : lower(c.scheme)
  let ui, host, port
  if (c.authority !== undefined) {
    const a = splitAuthority(c.authority)
    ui = a.userinfo; host = a.host; port = a.port
  }
  check(c.path, 'path')
  if (ui !== undefined) check(ui, 'userinfo')
  if (host !== undefined) check(host, 'host')
  if (c.query !== undefined) check(c.query, 'query')
  if (c.fragment !== undefined) check(c.fragment, 'fragment')
  let path = removeDots(pct(c.path))
  let out = ''
  if (scheme !== undefined) out += scheme + ':'
  if (c.authority !== undefined) {
    out += '//'
    if (ui !== undefined) out += pct(ui) + '@'
    out += lower(pct(host))
    if (port !== undefined && port !== '' && port !== DEFAULT_PORTS[scheme]) out += ':' + port
    if (path === '') path = '/'
  }
  out += path
  if (c.query !== undefined) out += '?' + pct(c.query)
  if (c.fragment !== undefined) out += '#' + pct(c.fragment)
  return out
}

function resolve(base, ref) {
  const b = parse(base)
  const r = parse(ref)
  if (b.scheme === undefined) throw new Fail('the base has no scheme')
  if (r.scheme !== undefined) return { ...r, path: removeDots(r.path) }
  if (r.authority !== undefined) return { ...r, scheme: b.scheme, path: removeDots(r.path) }
  const t = { scheme: b.scheme, authority: b.authority, fragment: r.fragment }
  if (r.path === '') {
    t.path = b.path
    t.query = r.query !== undefined ? r.query : b.query
  } else {
    t.query = r.query
    if (r.path.startsWith('/')) t.path = removeDots(r.path)
    else {
      let merged
      if (b.authority !== undefined && b.path === '') merged = '/' + r.path
      else {
        const i = b.path.lastIndexOf('/')
        merged = i < 0 ? r.path : b.path.slice(0, i + 1) + r.path
      }
      t.path = removeDots(merged)
    }
  }
  return t
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }
  const lines = require_stdin().split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const out = []
  for (let n = 1; n <= lines.length; n++) {
    const line = lines[n - 1]
    try {
      if (args[0] === 'normalize') out.push(normalize(parse(line)))
      else {
        const sp = line.indexOf(' ')
        if (sp < 0) throw new Fail('expected a base and a reference')
        out.push(normalize(resolve(line.slice(0, sp), line.slice(sp + 1))))
      }
    } catch (e) {
      if (!(e instanceof Fail)) throw e
      process.stderr.write(`error: line ${n}: ${e.message}\n`)
      process.exit(2)
    }
  }
  if (out.length) process.stdout.write(out.join('\n') + '\n')
}

function require_stdin() {
  return new TextDecoder().decode(readAll())
}

function readAll() {
  const fs = process.getBuiltinModule('node:fs')
  const chunks = []
  const buf = Buffer.alloc(65536)
  for (;;) {
    let n
    try { n = fs.readSync(0, buf, 0, buf.length, null) } catch (e) {
      if (e.code === 'EAGAIN') continue
      if (e.code === 'EOF') break
      throw e
    }
    if (n === 0) break
    chunks.push(Buffer.from(buf.subarray(0, n)))
  }
  return Buffer.concat(chunks)
}

main()
