{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

let names = null
const ballots = []
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const t = line.split(/\s+/)
  const err = (m) => fail(`error: line ${n}: ${m}`)
  if (t[0] === 'candidates') {
    if (names !== null || ballots.length) err('candidates must be declared once, before any ballot')
    if (t.length < 2) err('expected candidates <name>...')
    const seen = new Set()
    for (const nm of t.slice(1)) {
      if (!/^[A-Za-z0-9_-]+$/.test(nm)) err(`invalid candidate name ${nm}`)
      if (seen.has(nm)) err(`candidate ${nm} is declared twice`)
      seen.add(nm)
    }
    names = t.slice(1)
  } else if (t[0] === 'ballot') {
    if (names === null) err('candidates must be declared once, before any ballot')
    if (t.length < 3) err('expected ballot <count> <candidate>...')
    if (!/^[1-9][0-9]*$/.test(t[1])) err('count must be a positive integer')
    const seen = new Set()
    for (const nm of t.slice(2)) {
      if (!names.includes(nm)) err(`unknown candidate ${nm}`)
      if (seen.has(nm)) err(`candidate ${nm} is repeated`)
      seen.add(nm)
    }
    ballots.push({ count: Number(t[1]), prefs: t.slice(2) })
  } else {
    err(`unknown directive ${t[0]}`)
  }
})
if (names === null) fail('error: no candidates')

const continuing = new Set(names)
const history = new Map(names.map((c) => [c, []]))
const out = []
let nrounds = 0
let result = 'no winner'
for (;;) {
  nrounds++
  const counts = new Map([...continuing].map((c) => [c, 0]))
  let active = 0
  let total = 0
  for (const b of ballots) {
    total += b.count
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  for (const [c, v] of counts) history.get(c).push(v)
  const listed = [...counts.keys()].sort((a, b) => counts.get(b) - counts.get(a) || (a < b ? -1 : a > b ? 1 : 0))
  const head = `round ${nrounds}: ${listed.map((c) => `${c}=${counts.get(c)}`).join(' ')} exhausted=${total - active}`
  out.push(head)
  if (active === 0) break
  const win = listed.find((c) => counts.get(c) * 2 > active)
  if (win !== undefined) {
    result = `winner ${win}`
    break
  }
  let set = listed.filter((c) => counts.get(c) === Math.min(...counts.values()))
  while (set.length > 1) {
    let k = 0
    while (k < nrounds && set.every((c) => history.get(c)[k] === history.get(set[0])[k])) k++
    if (k === nrounds) break
    const m = Math.min(...set.map((c) => history.get(c)[k]))
    set = set.filter((c) => history.get(c)[k] === m)
  }
  const elim = set.length === 1 ? set[0] : set.reduce((a, b) => (a > b ? a : b))
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
if (result === 'no winner') {
  // fallthrough
}
process.stdout.write((mode === 'rounds' ? out.join('\n') + '\n' : `rounds ${nrounds}\n`) + result + '\n')
EOF
node --test test/*.test.js 2>&1 | tail -8","description":"Write cli and run tests"}

