      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  for (const [c, v] of counts) history.get(c).push(v)
  const listed = [...counts.keys()].sort((a, b) => counts.get(b) - counts.get(a) || (a < b ? -1 : a > b ? 1 : 0))
  const head = `round ${nrounds}: ${listed.map((c) => `${c}=${counts.get(c)}`).join(' ')} exhausted=${total - active}`
  out.push(head)
  if (active === 0) break
  const win = listed.find((c) => counts.get(c) * 2 > active)
  if (win !== undefined) {
    result = `winner ${win}`
    break
  }
  let set = listed.filter((c) => counts.get(c) === Math.min(...counts.values()))
  while (set.length > 1) {
    let k = 0
    while (k < nrounds && set.every((c) => history.get(c)[k] === history.get(set[0])[k])) k++
    if (k === nrounds) break
    const m = Math.min(...set.map((c) => history.get(c)[k]))
    set = set.filter((c) => history.get(c)[k] === m)
  }
  const elim = set.length === 1 ? set[0] : set.reduce((a, b) => (a > b ? a : b))
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
if (result === 'no winner') {
  // fallthrough
}
process.stdout.write((mode === 'rounds' ? out.join('\n') + '\n' : `rounds ${nrounds}\n`) + result + '\n')
