const PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>', '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    const sl = line, sc = col, start = i
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      let depth = 0
      while (true) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') { adv(); adv(); depth++ }
        else if (cs[i] === '*' && cs[i + 1] === '/') { adv(); adv(); if (--depth === 0) break }
        else adv()
      }
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      adv(); adv()
      let v = ''
      while (true) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = adv()
        if (d === '"') break
        v += d
      }
      tokens.push([sl, sc, 'rawstring', JSON.stringify(v)])
      continue
    }
    if (isIdStart(c)) {
      while (i < n && isIdPart(cs[i])) adv()
      const s = cs.slice(start, i).join('')
      tokens.push([sl, sc, KEYWORDS.has(s) ? 'keyword' : 'ident', s])
      continue
    }
    if (isDigit(c)) {
      // digit run with single underscores between digits of the run
      const run = (ok) => {
        let any = false
        while (i < n) {
          if (ok(cs[i])) { adv(); any = true }
          else if (cs[i] === '_' && any && ok(cs[i - 1]) && ok(cs[i + 1])) adv()
          else break
        }
        return any
      }
      let bad = false
      const p = cs[i + 1]
      if (c === '0' && p !== undefined && 'xXbBoO'.includes(p)) {
        adv(); adv()
        const ok = 'xX'.includes(p) ? isHex : 'bB'.includes(p) ? isBin : isOct
        if (!run(ok)) bad = true
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { adv(); run(isDigit) }
        if (cs[i] === 'e' || cs[i] === 'E') {
          const a = cs[i + 1]
          if (isDigit(a) || ((a === '+' || a === '-') && isDigit(cs[i + 2]))) {
            adv()
            if (!isDigit(cs[i])) adv()
            run(isDigit)
          }
        }
      }
      if (bad || isIdPart(cs[i])) {
        while (i < n && isIdPart(cs[i])) adv()
        throw new ScanError(sl, sc, 'invalid number ' + cs.slice(start, i).join(''))
      }
      tokens.push([sl, sc, 'number', cs.slice(start, i).join('')])
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      while (true) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const bl = line, bc = col
        const d = cs[i]
        if (d === '\n') throw new ScanError(bl, bc, 'newline in string')
        adv()
        if (d === '"') break
        if (d !== '\\') { v += d; continue }
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = cs[i]
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', '0': '\0' }
        if (e in simple) { adv(); v += simple[e] }
        else if (e === 'x' && isHex(cs[i + 1]) && isHex(cs[i + 2])) {
          adv(); const h = adv() + adv()
          v += String.fromCodePoint(parseInt(h, 16))
        } else if (e === 'u' && cs[i + 1] === '{') {
          let j = i + 2
          let h = ''
          while (isHex(cs[j])) h += cs[j++]
          if (h === '' || cs[j] !== '}' || parseInt(h, 16) > 0x10ffff) {
            throw new ScanError(bl, bc, 'invalid escape \\u')
          }
          while (i <= j) adv()
          v += String.fromCodePoint(parseInt(h, 16))
        } else throw new ScanError(bl, bc, 'invalid escape \\' + e)
      }
      tokens.push([sl, sc, 'string', JSON.stringify(v)])
      continue
    }
    const two = c + (cs[i + 1] ?? '')
    const p = PUNCT.find((q) => (q.length === 2 ? q === two : q === c))
    if (p) {
      for (let k = 0; k < p.length; k++) adv()
      tokens.push([sl, sc, 'punct', p])
      continue
    }
    throw new ScanError(sl, sc, 'unexpected character ' + c)
  }
  return tokens
}

const input = readFileSync(0, 'utf8')
let tokens
try {
  tokens = scan(input)
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
  process.exit(2)
}
let out = ''
if (mode === 'tokens') {
  for (const [l, c, k, b] of tokens) out += `${l}:${c} ${k} ${b}\n`
} else {
  for (const k of ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']) {
    out += `${k} ${tokens.filter((t) => t[2] === k).length}\n`
  }
  out += `total ${tokens.length}\n`
}
process.stdout.write(out)
EOF
