    const nxt = freeAt.filter((f) => f > t)
    if (!nxt.length) break
    t = nxt.reduce((a, b) => (b < a ? b : a))
  }
  ran.forEach((r, i) => out.push(`worker ${i}:` + r.map((x) => ' ' + x).join('')))
  out.push(`makespan ${total2()}`)
  function total2() {
    let m = 0n
    for (const f of done.values()) if (f > m) m = f
    return m
  }
}
process.stdout.write(out.join('\n') + '\n')
EOF
