const keyName = (k) => colName(Math.floor(k / 1000)) + (k % 1000)

// ---- lexer / parser ----
function lex(s) {
  const out = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
