      return node.v.toString()
    default:
      return JSON.stringify(node.v)
  }
}

function toKeys(node, path, out) {
  if (node.t === 'table') {
    for (const k of sortedKeys(node.m)) {
      const c = node.m.get(k)
      const p = join(path, k)
      out.push(`${p} ${c.t}`)
      toKeys(c, p, out)
    }
  } else if (node.t === 'array') {
    node.items.forEach((c, idx) => {
      const p = `${path}[${idx}]`
      out.push(`${p} ${c.t}`)
      toKeys(c, p, out)
