const state = new Map()
const stack = []
const dfs = (t) => {
  state.set(t, 1)
  stack.push(t)
  for (const d of dl.get(t)) {
    if (state.get(d) === 1) {
      const cyc = stack.slice(stack.indexOf(d)).concat(d)
      fail('error: cycle: ' + cyc.join(' -> '), 3)
    }
    if (!state.has(d)) dfs(d)
