  if (finish.has(t)) return
  let s = 0n, dp = 0
  for (const d of dl.get(t)) {
    calc(d)
    if (finish.get(d) > s) s = finish.get(d)
    if (depth.get(d) + 1 > dp) dp = depth.get(d) + 1
  }
  start.set(t, s); finish.set(t, s + cost.get(t)); depth.set(t, dp)
