import { readFileSync } from 'node:fs'

class Fail extends Error {}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let cands = null
  const ballots = []
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    const fail = (m) => { throw new Fail(`line ${n}: ${m}`) }
    if (t[0] === 'candidates') {
      if (cands) fail('candidates must be declared once, before any ballot')
      if (t.length < 2) fail('expected candidates <name>...')
      const seen = new Set()
      for (const name of t.slice(1)) {
        if (!/^[A-Za-z0-9_-]+$/.test(name)) fail(`invalid candidate name ${name}`)
        if (seen.has(name)) fail(`candidate ${name} is declared twice`)
        seen.add(name)
      }
      cands = t.slice(1)
    } else if (t[0] === 'ballot') {
      if (!cands) fail('candidates must be declared once, before any ballot')
      if (t.length < 3) fail('expected ballot <count> <candidate>...')
      if (!/^[1-9][0-9]*$/.test(t[1])) fail('count must be a positive integer')
      const seen = new Set()
      for (const name of t.slice(2)) {
        if (!cands.includes(name)) fail(`unknown candidate ${name}`)
        if (seen.has(name)) fail(`candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
    } else fail(`unknown directive ${t[0]}`)
  })
  if (!cands) throw new Fail('no candidates')
  return { cands, ballots }
}

const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'rounds' && mode[0] !== 'tally')) {
  process.stderr.write('error: usage: cli.js rounds|tally\n')
  process.exit(2)
}

let election
try {
  election = parse(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}

const { cands, ballots } = election
const alive = new Set(cands)
const history = []
const out = []
let winner = null
for (let k = 1; ; k++) {
  const counts = new Map([...alive].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => alive.has(p))
    if (c !== undefined) { counts.set(c, counts.get(c) + b.count); active += b.count }
  }
  let total = 0n
  for (const b of ballots) total += b.count
  history.push(counts)
  const listed = [...counts.entries()].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
  out.push(`round ${k}: ${listed.map(([c, v]) => `${c}=${v}`).concat(`exhausted=${total - active}`).join(' ')}`)
  if (active === 0n) break
  const w = listed.find(([, v]) => v * 2n > active)
  if (w) { winner = w[0]; break }
  let min = null
  for (const v of counts.values()) if (min === null || v < min) min = v
  let tied = [...alive].filter((c) => counts.get(c) === min)
  for (let r = 0; r < history.length && tied.length > 1; r++) {
    let lo = null
    for (const c of tied) { const v = history[r].get(c); if (lo === null || v < lo) lo = v }
    const keep = tied.filter((c) => history[r].get(c) === lo)
    if (keep.length < tied.length) { tied = keep; r = -1 }
  }
  const elim = tied.reduce((a, b) => (a > b ? a : b))
  alive.delete(elim)
  out.push(`eliminated ${elim}`)
}
const end = winner ? `winner ${winner}` : 'no winner'
if (mode[0] === 'rounds') process.stdout.write(out.join('\n') + '\n' + end + '\n')
else process.stdout.write(`rounds ${history.length}\n${end}\n`)
