  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^[^ \t]*/.exec(s)
  const raw = m[0]
  const content = s.slice(raw.length).replace(/^[ \t]+/, '')
  const addr = parseAddress(raw)
  if (!addr) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${raw}\n`)
    process.exit(2)
  }
  if (cells.has(addr.key)) {
    process.stderr.write(`error: line ${i + 1}: cell ${raw} is declared twice\n`)
    process.exit(2)
