{"file_path":"src/parse.js","content":"// Returns an AST, or null when the grammar rejects the body.
const CMP = new Set(['=', '<>', '<', '<=', '>', '>='])

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: m[0] })
      i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] })
      i += m[0].length
    } else if (s.startsWith('<>', i) || s.startsWith('<=', i) || s.startsWith('>=', i)) {
      toks.push({ k: 'op', v: s.slice(i, i + 2) })
      i += 2
    } else if ('^*/+-=<>():,'.includes(ch)) {
      toks.push({ k: 'op', v: ch })
      i++
    } else return null
  }
  return toks
}

export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const fail = () => { throw new Error('syntax') }
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  const expect = (v) => { if (!isOp(v)) fail(); p++ }

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && CMP.has(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { t: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    if (p >= toks.length) fail()
    const tk = toks[p++]
    if (tk.k === 'num') return { t: 'num', v: Number(tk.v) }
    if (tk.k === 'word') {
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++ } else {
          for (;;) {
            args.push(cmp())
            if (isOp(',')) { p++; continue }
            expect(')')
            break
          }
        }
        return { t: 'call', name: tk.v.toUpperCase(), args }
      }
      const u = tk.v.toUpperCase()
      if (isOp(':')) {
        p++
        if (p >= toks.length || toks[p].k !== 'word') fail()
        return { t: 'range', a: tk.v, b: toks[p++].v }
      }
      if (u === 'TRUE') return { t: 'bool', v: true }
      if (u === 'FALSE') return { t: 'bool', v: false }
      return { t: 'ref', name: tk.v }
    }
    if (tk.v === '(') {
      const e = cmp()
      expect(')')
      return { t: 'paren', e }
    }
    return fail()
  }

  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch {
    return null
  }
}
"}

{"file_path":"src/eval.js","content":"import { parseAddress, colName } from './addr.js'

const ERRORS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const num = (v) => ({ t: 'n', v })
const err = (v) => ({ t: 'e', v })
const ZERO = num(0)

function validRanges(n, ok) {
  // A range is only legal as a direct function argument.
  if (!n) return true
  switch (n.t) {
    case 'range': return ok
    case 'bin': return validRanges(n.l, false) && validRanges(n.r, false)
    case 'un': case 'paren': return validRanges(n.e, false)
    case 'call': return n.args.every((a) => validRanges(a, true))
  }
  return true
}

function cmpCodePoints(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}

const rank = { n: 0, s: 1, b: 2 }

export class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.active = new Set()
  }

  format(v) {
    switch (v.t) {
      case 'n': return String(Number(v.v.toPrecision(10)))
      case 'b': return v.v ? 'TRUE' : 'FALSE'
      default: return v.v
    }
  }

  get(key) {
    if (this.memo.has(key)) return this.memo.get(key)
    if (this.active.has(key)) return err('#CYCLE!')
    const cell = this.cells.get(key)
    if (!cell) return ZERO
    this.active.add(key)
    let v
    if (cell.content[0] === '=') {
      if (!cell.ast || !validRanges(cell.ast, false)) v = err('#ERR!')
      else v = this.ev(cell.ast)
    } else v = literal(cell.content)
    this.active.delete(key)
    this.memo.set(key, v)
    return v
  }

  ref(name) {
    const a = parseAddress(name)
    return a ? this.get(a.key) : err('#REF!')
  }

  expand(n) {
    const a = parseAddress(n.a), b = parseAddress(n.b)
    if (!a || !b) return [err('#REF!')]
    const out = []
    for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
      for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push(this.get(colName(c) + r))
    return out
  }

  toNum(v) {
    if (v.t === 'n') return v
    if (v.t === 'b') return num(v.v ? 1 : 0)
    if (v.t === 's') return err('#VALUE!')
    return v
  }

  fin(x) {
    return Number.isFinite(x) ? num(x) : err('#DIV/0!')
  }

  ev(n) {
    switch (n.t) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'paren': return this.ev(n.e)
      case 'ref': return this.ref(n.name)
      case 'range': return err('#ERR!')
      case 'un': {
        const v = this.toNum(this.ev(n.e))
        if (v.t === 'e') return v
        return n.op === '-' ? num(-v.v) : v
      }
      case 'bin': return this.bin(n)
      case 'call': return this.call(n)
    }
    return err('#ERR!')
  }

  bin(n) {
    const l = this.ev(n.l), r = this.ev(n.r)
    if (l.t === 'e') return l
    if (r.t === 'e') return r
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      let d
      if (l.t !== r.t) d = rank[l.t] - rank[r.t]
      else if (l.t === 's') d = cmpCodePoints(l.v, r.v)
      else d = Number(l.v) - Number(r.v)
      if (l.t === r.t && l.t !== 's') d = l.v < r.v ? -1 : l.v > r.v ? 1 : 0
      const res = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
      return { t: 'b', v: res }
    }
    const a = this.toNum(l)
    if (a.t === 'e') return a
    const b = this.toNum(r)
    if (b.t === 'e') return b
    switch (n.op) {
      case '+': return this.fin(a.v + b.v)
      case '-': return this.fin(a.v - b.v)
      case '*': return this.fin(a.v * b.v)
      case '/': return b.v === 0 ? err('#DIV/0!') : this.fin(a.v / b.v)
      case '^': return this.fin(Math.pow(a.v, b.v))
    }
    return err('#ERR!')
  }

  call(n) {
    const name = n.name
    const argc = n.args.length
    if (name === 'IF') {
      if (argc !== 3) return err('#ERR!')
      const c = this.ev(n.args[0])
      if (c.t === 'e') return c
      let truth
      if (c.t === 'b') truth = c.v
      else if (c.t === 'n') truth = c.v !== 0
      else return err('#VALUE!')
      return this.ev(n.args[truth ? 1 : 2])
    }
    if (name === 'ABS') {
      if (argc !== 1) return err('#ERR!')
      const vs = this.values(n.args)
      if (vs.length !== 1) return err('#ERR!')
      const v = this.toNum(vs[0])
      return v.t === 'e' ? v : num(Math.abs(v.v))
    }
    if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return err('#NAME?')
    if (argc < 1) return err('#ERR!')
    const vs = this.values(n.args)
    const first = vs.find((v) => v.t === 'e')
    if (first) return first
    if (name === 'COUNT') return num(vs.filter((v) => v.t === 'n').length)
    const nums = []
    for (const v of vs) {
      const x = this.toNum(v)
      if (x.t === 'e') return x
      nums.push(x.v)
    }
    if (name === 'SUM') return this.fin(nums.reduce((a, b) => a + b, 0))
    if (name === 'AVG') return nums.length ? this.fin(nums.reduce((a, b) => a + b, 0) / nums.length) : err('#DIV/0!')
    if (!nums.length) return ZERO
    return num(name === 'MIN' ? Math.min(...nums) : Math.max(...nums))
  }

  values(args) {
    const out = []
    for (const a of args) {
      if (a.t === 'range') out.push(...this.expand(a))
      else out.push(this.ev(a))
    }
    return out
  }
}

function literal(s) {
  if (s === '') return ZERO
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) return num(Number(s))
  if (ERRORS.has(s)) return err(s)
  return { t: 's', v: s }
}
"}

